// Single-precision sinf/cosf/powf of the Windows Universal CRT (ucrtbase.dll) as portable software: a mechanical lift of
// the CRT's own x64 machine code (src/dotnet/ucrt_libm_gen.cpp, generated by tools/libm/gen_main.py ucrt). Unity's native
// player code (UnityEngine.Random.onUnitSphere/insideUnitCircle, Quaternion.AngleAxis) calls these; other libms differ in
// the last bit of float results for ~0.1% of inputs, so the capture gates need this on non-Windows hosts. Bit-exact with
// ucrtbase.dll on every host; the Windows build uses the host's own sinf/cosf/powf unless KSP_LIBM_PORTABLE is set.
#pragma once

namespace ksp::dotnet::ucrt {

float sinf(float x);
float cosf(float x);
float powf(float x, float y);

void SetFma3(bool on);  // ucrtbase picks its FMA3 code path at start-up; default true (the capture machine had FMA3)
bool GetFma3();

}  // namespace ksp::dotnet::ucrt

namespace ksp::dotnet {
// What Unity's native code gets from sinf/cosf/powf: the host UCRT on Windows (default), the portable lift elsewhere
// (or when KSP_LIBM_PORTABLE / env KSPCORE_LIBM_PORTABLE is set). Implemented in math.cpp.
float NativeSinf(float x);
float NativeCosf(float x);
float NativePowf(float x, float y);
}  // namespace ksp::dotnet
